  ],
  "claims": [
    {
      "claim": "The low-F SERM contexts (raloxifene ~2%, bazedoxifene ~6%) are attributed to phenolic glucuronidation and first-pass metabolism; the query has no phenolic hydroxyl, so this mechanism is not transferable.",
      "card_ids": ["C01", "C02", "C11", "C18"]
    },
    {
      "claim": "Other low-F L1 contexts are structurally distinct chemotypes (tolperisone, pyronaridine, avoralstat, avanafil, tetracycline/toceranib mismatch, CDP323, lisofylline) with different absorption and first-pass liabilities; their low values do not affirm F<20% for the 4-anilinoquinazoline acrylamide query.",
      "card_ids": ["C06", "C09", "C08", "C21", "C14", "C04", "C13"]
    },
    {
      "claim": "L2 records show that non-phenolic, lipophilic, basic-amine kinase-inhibitor-like chemotypes can achieve F>=20% in animals or formulations, including toceranib 76.9% in dogs, compound 17p 27-100% across species, and CDP323 >25% preclinically.",
      "card_ids": ["C54", "C72", "C35", "C42", "C49", "C40"]
    },
    {
      "claim": "L3 oral exposure records for afatinib, the closest structural analog sharing the 4-anilinoquinazoline core, 3-chloro-4-fluoroanilino group, and the same acrylamide warhead, show measurable systemic exposure after oral dosing: geometric mean AUC0-24 of 459 ng·h/mL at 50 mg and steady-state Cmax of 77 ng/mL at 50 mg, with exposure also present at 20 mg (AUCτ 380 ng·h/mL, Cmax 24.5 ng/mL).",
      "card_ids": ["C85", "C91", "C96", "C102", "C111"]
    },
    {
      "claim": "Other 4-anilinoquinazoline and related oral kinase inhibitors in L3 show meaningful oral exposure: gefitinib Cmax 39.5 µg/L and AUC24 502 µg·h/L at 100 mg; vandetanib Cmax ~156-179 ng/mL at 300 mg; erlotinib Cmax ~1.2-1.8 µg/mL at 150 mg; lapatinib Cmax 1.63 µg/mL in dogs; bosutinib AUC∞ 2268 ng·h/mL at 500 mg.",
      "card_ids": ["C126", "C88", "C117", "C83", "C92", "C110", "C131", "C97", "C112", "C101", "C86"]
    },
    {
      "claim": "The low-oral-exposure L3 records (batefenterol parent non-quantifiable; DA-8010 pg/mL-level exposure) belong to structurally distinct chemotypes and do not transfer to the query's 4-anilinoquinazoline acrylamide scaffold.",
      "card_ids": ["C100", "C99", "C82", "C84", "C104", "C120"]
    }
  ],
  "new_evidence_assessment": [
    {
      "family": "oral_auc_cmax_exposure",
      "applicability": "high",
      "direction": "supportive",
      "decision_effect": "strengthened",
      "card_ids": [
        "C85", "C91", "C96", "C102", "C111",
        "C126", "C88", "C117", "C83", "C92", "C110", "C131",
        "C97", "C112", "C101", "C86"
      ]
    }
  ],
  "evidence_gaps": [
    "No direct absolute oral bioavailability measurement for the query molecule is provided.",
    "No matched oral-versus-IV exposure data for the query or for afatinib are provided in L3; AUC/Cmax alone cannot quantify F.",
    "Afatinib is a close analog but not identical; the query replaces the tetrahydrofuran-3-yloxy group with methoxy and dimethylamino with piperidine, which may alter absorption and first-pass extraction.",
    "Metabolic stability and first-pass extraction for the query are not experimentally characterized.",
    "The L3 exposure records are mostly from cancer patients or healthy subjects at therapeutic doses, not from a dedicated absolute bioavailability study."
  ],
  "decision_summary": "L3 oral exposure records for afatinib, the closest structural analog, demonstrate measurable systemic exposure after oral dosing, and other 4-anilinoquinazoline kinase inhibitors show meaningful oral AUC/Cmax; no transferable low-F evidence appears in this level. The prior high prediction is strengthened, though confidence remains moderate because no direct F value or IV comparator is available."
}

